package com.sarathi.geckotest;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.KeyStore;import org.json.JSONObject;
final class SecureSettings {
 private static javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("mparivahan-config")){KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("mparivahan-config",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return (javax.crypto.SecretKey)store.getKey("mparivahan-config",null);}
 static synchronized JSONObject read(Context c)throws Exception{String saved=c.getSharedPreferences("secure",0).getString("config","");if(saved.isEmpty())return new JSONObject();String[] fields=saved.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(fields[0],Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(fields[1],Base64.NO_WRAP)),java.nio.charset.StandardCharsets.UTF_8));}
 static synchronized void write(Context c,JSONObject values)throws Exception{JSONObject merged=read(c);for(String k:new String[]{"botToken","chatId","chatId2"})if(values.has(k))merged.put(k,values.getString(k));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String data=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(merged.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!c.getSharedPreferences("secure",0).edit().putString("config",data).commit())throw new IllegalStateException("Could not save Telegram settings");}
}
